public class ProducerConsumerBuffer<T> {
    private final java.util.Queue<T> queue = new java.util.LinkedList<>();
    private final int capacity;

    public ProducerConsumerBuffer(int capacity) {
        this.capacity = capacity;
    }

    public synchronized void produce(T item) throws InterruptedException {
        while (queue.size() == capacity) {
            wait(); // Releases monitor and waits for consumer consumption
        }
        queue.offer(item);
        notifyAll(); // Wake up any waiting consumers (and producers)
    }

    public synchronized T consume() throws InterruptedException {
        while (queue.isEmpty()) {
            wait(); // Releases monitor and waits for producer generation
        }
        T item = queue.poll();
        notifyAll(); // Wake up any waiting producers
        return item;
    }
}
